import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as s,o as t,af as n,b as h,w as a,a as l,G as d,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const q=JSON.parse('{"title":"Model Lifecycle (Bridge)","description":"The guide to the Model Lifecycle group — two chains converge at Inference; what engineering question each of the four in-group pages answers (LLM mental model, architecture, data/pretraining/scaling, post-training), with training math and derivations owned by Learn LLM.","frontmatter":{"title":"Model Lifecycle (Bridge)","description":"The guide to the Model Lifecycle group — two chains converge at Inference; what engineering question each of the four in-group pages answers (LLM mental model, architecture, data/pretraining/scaling, post-training), with training math and derivations owned by Learn LLM.","domain":"tech","tags":["tech","orientation","bridge","model-lifecycle"],"navOrder":10,"topicId":"model-lifecycle-bridge","layer":"1","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/"}],"prerequisites":["site-boundaries"],"next":["llm-mental-model"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/01-model-lifecycle/index.md","filePath":"tech/01-model-lifecycle/index.md","lastUpdated":1791165915000}'),g={name:"tech/01-model-lifecycle/index.md"};function p(u,e,m,f,b,y){const r=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=n('<blockquote><p><strong>Group</strong>: 01 · Model Lifecycle (bridge group) | <strong>Exit of the group above</strong>: you can decide knowledge ownership and pick the lowest-complexity option for a need (00-map group) | <strong>Exit of this group</strong>: you can state how the model lifecycle affects engineering decisions (when prompt is not enough, how to choose models, how cost works) and know which Learn LLM chapter holds the deep principles <strong>Prerequisites</strong>: <a href="./../00-map/site-boundaries.html">Site Boundaries and Knowledge Ownership</a> | <strong>Next</strong>: <a href="./llm-mental-model.html">The LLM Mental Model (Bridge)</a>; after this group, enter the <a href="./../02-inference-interface/">02-inference-interface group</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Lead with the answer</strong>: the model lifecycle (data, pretraining, post-training, inference) must have a place on the tech map — otherwise you cannot understand what your system sits on — but this repo covers it only to the depth that <strong>affects engineering decisions</strong>. Training math, experiment details, and full derivations belong to <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>. This is a bridge group: four pages each bridge one conceptual domain, and their bodies carry only &quot;concept position → why an application engineer needs it → decision impact → link to Learn LLM&quot;, never copied derivations.</p><h3 id="mental-model-two-chains-converging-at-inference" tabindex="-1">Mental model: two chains converging at Inference <a class="header-anchor" href="#mental-model-two-chains-converging-at-inference" aria-label="Permalink to &quot;Mental model: two chains converging at Inference&quot;">​</a></h3>',4)),(t(),h(c,null,{default:a(()=>[d(r,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20A%20%5B%22Model%20lifecycle%20chain%20%E2%80%94%20deep%20principles%20owned%20by%20Learn%20LLM%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%22ML%20%2F%20DL%20basics%22%5D%20--%3E%20A2%5B%22LLM%20mental%20model%22%5D%0A%20%20%20%20%20%20%20%20A2%20--%3E%20A3%5B%22Data%20%2F%20Pretraining%20%2F%20Scaling%22%5D%0A%20%20%20%20%20%20%20%20A3%20--%3E%20A4%5B%22Post-training%3A%20SFT%20%C2%B7%20RLHF%20%C2%B7%20PEFT%22%5D%0A%20%20%20%20%20%20%20%20A4%20--%3E%20A5%5B%22Inference%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20B%20%5B%22AI%20systems%20engineering%20chain%20%E2%80%94%20this%20repo's%20canonical%20main%20line%22%5D%0A%20%20%20%20%20%20%20%20B1%5B%22Inference%20%2F%20Model%20Interface%22%5D%20--%3E%20B2%5B%22Context%22%5D%0A%20%20%20%20%20%20%20%20B2%20--%3E%20B3%5B%22Grounding%20%2F%20RAG%22%5D%0A%20%20%20%20%20%20%20%20B3%20--%3E%20B4%5B%22Tools%20%2F%20Action%22%5D%0A%20%20%20%20%20%20%20%20B4%20--%3E%20B5%5B%22Agent%20Runtime%20%2F%20State%22%5D%0A%20%20%20%20%20%20%20%20B5%20--%3E%20B6%5B%22Interoperability%22%5D%0A%20%20%20%20%20%20%20%20B6%20--%3E%20B7%5B%22Production%20%2F%20Operations%22%5D%0A%20%20%20%20end%0A%20%20%20%20A5%20%3D%3D%3E%7Cconverge%7C%20B1%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<p>Every line of AI application code you write starts from the end of the left chain (Inference). The left chain decides &quot;what this model is and what it can do&quot;; the right chain decides &quot;what you build with it&quot;. The chains converge at Inference / Model Interface — which is why the next group (02-inference-interface) opens with the interface contract, not model architecture.</p><h3 id="in-group-navigation-4-pages-in-order" tabindex="-1">In-group navigation (4 pages, in order) <a class="header-anchor" href="#in-group-navigation-4-pages-in-order" aria-label="Permalink to &quot;In-group navigation (4 pages, in order)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Page</th><th>Question it answers</th><th>One-line conclusion</th></tr></thead><tbody><tr><td><a href="./llm-mental-model.html">LLM mental model</a></td><td>What the model actually is</td><td>A parametrized conditional probability model: prompts invoke capability rather than inject knowledge, context is a hard constraint, temperature is a sampling parameter</td></tr><tr><td><a href="./architecture.html">Model architecture</a></td><td>How architecture terms become bills</td><td>No derivations needed, but translate Attention / RoPE / MoE / KV cache into context length and inference cost</td></tr><tr><td><a href="./data-pretraining-scaling.html">Data, pretraining, and scaling</a></td><td>Where the model&#39;s knowledge and ceiling come from</td><td>The capability ceiling freezes at pretraining: knowledge cutoff, pricing tiers, and task reliability all trace to this chain</td></tr><tr><td><a href="./post-training/">Post-training</a> (three-page subgroup)</td><td>When weights are worth touching</td><td>The engineering-decision bridges for SFT / RLHF / PEFT; exhaust prompt and RAG first</td></tr></tbody></table><h3 id="key-terms-full-names-at-first-use" tabindex="-1">Key terms (full names at first use) <a class="header-anchor" href="#key-terms-full-names-at-first-use" aria-label="Permalink to &quot;Key terms (full names at first use)&quot;">​</a></h3><ul><li><strong>SFT</strong> (Supervised Fine-Tuning): continued training on labeled examples that changes model behavior.</li><li><strong>RLHF</strong> (Reinforcement Learning from Human Feedback): training a reward model from human preference signals, then optimizing the policy against it.</li><li><strong>PEFT</strong> (Parameter-Efficient Fine-Tuning): training only small attached parameter sets (e.g. LoRA) to cut training cost.</li><li><strong>Scaling</strong>: the empirical regularity linking model size, data volume, and compute to capability.</li></ul><h2 id="_2-when-to-hop" tabindex="-1">2. When to Hop <a class="header-anchor" href="#_2-when-to-hop" aria-label="Permalink to &quot;2. When to Hop&quot;">​</a></h2><p>This group has no runnable artifact; substitute action (about 5 minutes): locate your concern on the diagram above (e.g. &quot;why won&#39;t the model reliably emit JSON&quot; → the junction between Post-training on the left chain and Context on the right), decide whether it is an engineering or a principles question (engineering questions take the right chain into this repo&#39;s groups; principles questions hop to Learn LLM), and record your stop point — this group&#39;s body stops at &quot;the lifecycle shapes interface properties&quot;. For a single question, enter directly via the table:</p><table tabindex="0"><thead><tr><th>Symptom / question</th><th>Where to go</th></tr></thead><tbody><tr><td>The model &quot;doesn&#39;t know&quot; a fact, or knowledge is stale</td><td><a href="./data-pretraining-scaling.html">Data, pretraining, and scaling</a> → <a href="./../04-grounding/rag.html">RAG</a></td></tr><tr><td>Bill / latency mismatched with expectations</td><td><a href="./architecture.html">Model architecture</a> → <a href="./../08-production/cost-performance.html">Cost and performance</a></td></tr><tr><td>Unstable output format</td><td><a href="./../02-inference-interface/structured-output.html">Structured output</a> (an interface-contract problem, not comprehension)</td></tr><tr><td>Want to truly understand training and inference internals</td><td>The <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM chapter index</a> (21 chapters)</td></tr></tbody></table><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><h3 id="why-the-left-chain-must-be-on-the-map-yet-not-expanded-here" tabindex="-1">Why the left chain must be on the map, yet not expanded here <a class="header-anchor" href="#why-the-left-chain-must-be-on-the-map-yet-not-expanded-here" aria-label="Permalink to &quot;Why the left chain must be on the map, yet not expanded here&quot;">​</a></h3><p><strong>It must be on the map</strong>: engineers who do not know that &quot;a model comes from a training pipeline&quot; treat every problem as a prompt problem — unaware that instruct-versus-base behavioral differences come from post-training, that context budgets come from inference-time cache structure, that a model version upgrade can change every engineering assumption. Without the left chain, every &quot;why&quot; on the right chain hangs in the air.</p><p><strong>It is not expanded here</strong>: training math, data engineering, and experimental method form a full discipline that Learn LLM already covers in 21 chapters (retrievedAt 2026-09-01). Any derivation copied here would create a second canonical that drifts over time (rules in <a href="./../00-map/site-boundaries.html">Site Boundaries</a>).</p><h3 id="what-the-convergence-point-means-for-engineering" tabindex="-1">What the convergence point means for engineering <a class="header-anchor" href="#what-the-convergence-point-means-for-engineering" aria-label="Permalink to &quot;What the convergence point means for engineering&quot;">​</a></h3><p>Inference is the only node the two chains share. It compresses the left chain&#39;s entire history (data, scale, post-training) into three engineering-visible interface properties:</p><ul><li><strong>Behavior</strong>: instruction following, format stability, refusal boundaries — the direct constraint target of the interface contracts (02-inference-interface group).</li><li><strong>Budget</strong>: context length and cache cost — the constraint source for context engineering (03-context group) and cost governance (08-production group).</li><li><strong>Capability boundary</strong>: what the model can and cannot do — an input assumption for tools and agent design (05-action and 06-agent-systems groups).</li></ul><p>In engineering you always consume a model through these three properties, not through its training details. That is the basis of the main-line stance &quot;the model is a replaceable external capability&quot;.</p><p><strong>Specification vs local measurement</strong>: not applicable — this group has no protocol specification; site-level &quot;measurement&quot; is the HTTP 200 status of the Learn LLM chapter URLs in the resource table (retrievedAt 2026-09-01).</p><h2 id="_4-engineering-decision-impact" tabindex="-1">4. Engineering Decision Impact <a class="header-anchor" href="#_4-engineering-decision-impact" aria-label="Permalink to &quot;4. Engineering Decision Impact&quot;">​</a></h2><h3 id="decision-table-changing-behavior-versus-adding-knowledge" tabindex="-1">Decision table: changing behavior versus adding knowledge <a class="header-anchor" href="#decision-table-changing-behavior-versus-adding-knowledge" aria-label="Permalink to &quot;Decision table: changing behavior versus adding knowledge&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Direction</th><th>Control</th><th>State</th><th>Trust domain</th><th>Lowest complexity</th></tr></thead><tbody><tr><td>Prompt + context</td><td>Read, instantly revisable</td><td>Adjustable per call</td><td>none</td><td>in-process</td><td>Lowest — start here by default</td></tr><tr><td>RAG (Retrieval-Augmented Generation)</td><td>Read, updates with data</td><td>You control indexing and refresh</td><td>Retrieval index</td><td>data-source boundary</td><td>Medium</td></tr><tr><td>SFT / RLHF / PEFT</td><td>Changes the model itself</td><td>Training pipeline + weight versioning</td><td>model weight versions</td><td>model supply chain</td><td>Highest — implementation not expanded here</td></tr></tbody></table><p><strong>Rule of thumb (this repo&#39;s position, not a quantified claim)</strong>: exhaust prompt + context first, then RAG; evaluate post-training only when you need to <strong>change the model&#39;s behavior</strong> (not to supply facts) and you have large amounts of high-quality labeled data, a training budget, and the matching engineering capability. Missing any one, fall back to RAG. The old training page&#39;s specific figures (&quot;10,000+ examples / $10,000+ budget&quot;) had no primary source and were deleted; they are not asserted here.</p><h3 id="the-three-engineering-decisions-the-lifecycle-shapes" tabindex="-1">The three engineering decisions the lifecycle shapes <a class="header-anchor" href="#the-three-engineering-decisions-the-lifecycle-shapes" aria-label="Permalink to &quot;The three engineering decisions the lifecycle shapes&quot;">​</a></h3><ol><li><strong>When prompt is not enough</strong>: missing knowledge → RAG first (04-grounding group); off behavior (tone, format, refusal policy) → tune prompt and few-shot examples; only after both are exhausted and the need is stable does post-training enter the conversation (in-group <a href="./post-training/">post-training/</a>).</li><li><strong>Model selection</strong>: base / instruct / fine-tuned / quantized variants differ widely in capability, cost, and deployment target; the math of quantization and inference runtimes belongs to Learn LLM, the selection framework to the 02-inference-interface group.</li><li><strong>Cost structure</strong>: training is a one-off large expenditure; inference and retrieval are ongoing variable costs; cost governance lives in the 08-production group, and training-cost estimation is out of scope here.</li></ol><p>Maintenance rule (in place of runbooks): when Learn LLM&#39;s chapter structure changes, re-verify every deep link in this group and update each page&#39;s <code>lastVerified</code>; when a new lifecycle-related engineering decision topic appears in this repo (e.g. model version upgrade strategy), expand it in the matching group&#39;s chapter and add only a one-line pointer here.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><ul><li><strong>Beginner</strong>: this guide + the <a href="./llm-mental-model.html">LLM mental model</a> — recite the two chains, the convergence point, and one correct mental model.</li><li><strong>Builder</strong>: enter the <a href="./../02-inference-interface/">02-inference-interface group</a> and start hands-on from the engineering side of the convergence — this group gives judgments, the interface group gives implementations.</li><li><strong>Operator</strong>: watch how model version upgrades affect contracts and cost (08-production group) — upgrades can change every assumption in this group.</li><li><strong>Researcher</strong>: descend through the Learn LLM chapters below into training and inference principles — the single canonical for deep principles.</li></ul><h3 id="resource-table-learn-llm-chapters-verified-via-its-chapter-index-retrievedat-2026-09-01" tabindex="-1">Resource table (Learn LLM chapters, verified via its chapter index, retrievedAt 2026-09-01) <a class="header-anchor" href="#resource-table-learn-llm-chapters-verified-via-its-chapter-index-retrievedat-2026-09-01" aria-label="Permalink to &quot;Resource table (Learn LLM chapters, verified via its chapter index, retrievedAt 2026-09-01)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Chapter</th><th>Canonical URL</th><th>Maps to this group&#39;s link</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>Chapter index (full 21-chapter map)</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/</a></td><td>Full expansion of both chains</td><td>Deep principles belong to Learn LLM</td><td>Pick chapters by link</td></tr><tr><td>Ch. 4 Character language model</td><td><a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/04-probabilistic-lm</a></td><td>LLM mental model</td><td>Conditional probability and sampling are the core mechanism</td><td>In-group <a href="./llm-mental-model.html">mental-model page</a></td></tr><tr><td>Ch. 7 Transformer</td><td><a href="https://llm.zenheart.site/chapters/07-attention" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/07-attention</a></td><td>Model architecture</td><td>From-scratch Attention / causal mask / multi-head</td><td>In-group <a href="./architecture.html">architecture page</a></td></tr><tr><td>Ch. 8 TinyGPT</td><td><a href="https://llm.zenheart.site/chapters/08-tinygpt" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/08-tinygpt</a></td><td>Data / Pretraining</td><td>Pretraining from scratch, visible end to end</td><td>In-group <a href="./data-pretraining-scaling.html">data-pretraining page</a></td></tr><tr><td>Ch. 6 Training Stability</td><td><a href="https://llm.zenheart.site/chapters/06-training-stability" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/06-training-stability</a></td><td>Pretraining engineering</td><td>Training stability is an engineering problem</td><td>—</td></tr><tr><td>Ch. 10 Post-training</td><td><a href="https://llm.zenheart.site/chapters/10-post-training" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/10-post-training</a></td><td>SFT / RLHF / PEFT</td><td>Post-training shapes behavior and instruction following</td><td>In-group <a href="./post-training/">post-training subgroup</a></td></tr><tr><td>Ch. 9 Inference and quantization</td><td><a href="https://llm.zenheart.site/chapters/09-inference-cache" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/09-inference-cache</a></td><td>Convergence: Inference</td><td>Inference-time caching constrains the context budget</td><td><a href="./../03-context/">03-context group</a></td></tr></tbody></table><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: if you find an engineering decision that <strong>cannot</strong> be made correctly without training details (e.g. VRAM estimation for local fine-tuning), it belongs to the in-group post-training subgroup or Learn LLM — sink the claim to the right owner instead of expanding this guide.</li><li>Open: the owner of LoRA / QLoRA selection effects is the in-group <a href="./post-training/peft.html">PEFT page</a>; Learn LLM deep links use the 2026-09-01 full verification as baseline, re-checked per the maintenance rule when chapter structure changes.</li></ul><h3 id="where-learn-ai-stops-where-to-continue" tabindex="-1">Where learn-ai stops / where to continue <a class="header-anchor" href="#where-learn-ai-stops-where-to-continue" aria-label="Permalink to &quot;Where learn-ai stops / where to continue&quot;">​</a></h3><ul><li>Training objectives and math (SFT / DPO / LoRA derivations): Learn LLM <a href="https://llm.zenheart.site/chapters/10-post-training" target="_blank" rel="noreferrer">chapter 10</a> — this repo stops here.</li><li>Start building with models: this repo&#39;s <a href="./../02-inference-interface/">02-inference-interface group</a> and the <a href="./../00-map/complexity-ladder.html">Complexity Decision Ladder</a>.</li><li>Proving results are shippable: <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>.</li></ul>',33))])}const k=i(g,[["render",p]]);export{q as __pageData,k as default};
